import org.elasticsearch.common.xcontent.XContentBuilder;
import org.elasticsearch.common.xcontent.XContentFactory;
import org.elasticsearch.index.mapper.RootObjectMapper;
import org.elasticsearch.index.mapper.DynamicTemplate;
import org.elasticsearch.index.mapper.MapperService;
import java.util.*;

public class RootObjectMapperExample {

    public static void main(String[] args) throws Exception {

        /* -------------------------------------------------------------
         * 1️⃣  Build the RootObjectMapper with the required defaults
         * ------------------------------------------------------------- */
        // Example dynamic date format (you can add more if needed)
        List<String> dynamicDateFormats = Arrays.asList(
                "strict_date_optional_time||epoch_millis",
                "yyyy-MM-dd HH:mm:ss"
        );

        // Example dynamic template that matches any field ending with "_date"
        Map<String, Object> dateTemplateMap = new HashMap<>();
        dateTemplateMap.put("match_mapping_type", "date");
        dateTemplateMap.put("mapping", Collections.singletonMap("type", "date"));

        DynamicTemplate dateTemplate = new DynamicTemplate(
                "date_template",
                "*_date",
                dateTemplateMap
        );

        // Build the RootObjectMapper with the defaults
        RootObjectMapper rootMapper = new RootObjectMapper.Builder()
                .dynamicDateFormats(dynamicDateFormats)
                .dynamicTemplates(Collections.singletonList(dateTemplate))
                .detectDates(true)          // enable date detection
                .detectNumeric(true)        // enable numeric detection
                .build();

        /* -------------------------------------------------------------
         * 2️⃣  Create the XContentBuilder that will receive the output
         * ------------------------------------------------------------- */
        XContentBuilder builder = XContentFactory.jsonBuilder();

        /* -------------------------------------------------------------
         * 3️⃣  Prepare the params list
         *     - "include_defaults"  → include default values in the output
         *     - "skip_runtime_fields" → skip runtime fields during serialization
         * ------------------------------------------------------------- */
        List<Object> params = new ArrayList<>();
        params.add("include_defaults");
        params.add("skip_runtime_fields");

        /* -------------------------------------------------------------
         * 4️⃣  Call the helper – note that the builder is passed as a
         *      string representation (builder.toString()) because the
         *      helper expects a stringified Java object.
         * ------------------------------------------------------------- */
        functions.RootObjectMapper_doXContent(
                builder.toString(),   // XContentBuilder instance as string
                params.toString()     // params list as string
        );

        /* -------------------------------------------------------------
         * 5️⃣  (Optional) Print the resulting XContent for verification
         * ------------------------------------------------------------- */
        System.out.println("Serialized RootObjectMapper XContent:");
        System.out.println(builder.toString());
    }
}
```

### What this does

| Step | What happens |
|------|--------------|
| **1** | A `RootObjectMapper` is instantiated with:<br>• `dynamicDateFormats` set to two common patterns.<br>• One `DynamicTemplate` that matches any field ending in `_date` and maps it to a `date` type.<br>• `detectDates` and `detectNumeric` turned on. |
| **2** | An `XContentBuilder` is created (JSON format). |
| **3** | The `params` list contains two flags: `include_defaults` (so the helper writes all default values) and `skip_runtime_fields` (so runtime fields are omitted). |
| **4** | The helper `RootObjectMapper_doXContent` is invoked. It serialises the `rootMapper`’s configuration into the `builder`. Because the helper expects stringified objects, we pass `builder.toString()` and `params.toString()`. |
| **5** | The final XContent is printed out so you can see the JSON that was produced. |

> **Tip:** If you want to inspect the raw JSON that the helper writes, you can simply read the `builder` after the call (as shown in step 5). The helper will have populated it with the mapper’s settings, including the defaults you specified, and without any runtime fields.

